// AdminServiceServer is the server API for AdminService service.
// All implementations must embed UnimplementedAdminServiceServer
// for forward compatibility.
type AdminServiceServer interface {
	// === 仪表盘 ===
	GetDashboard(context.Context, *emptypb.Empty) (*DashboardResponse, error)
	// === 用户管理 ===
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	UpdateUserRole(context.Context, *UpdateUserRoleRequest) (*emptypb.Empty, error)
	DisableUser(context.Context, *DisableUserRequest) (*emptypb.Empty, error)
	// === 题库管理 ===
	AdminListQuestions(context.Context, *AdminListQuestionsRequest) (*AdminListQuestionsResponse, error)
	CreateQuestion(context.Context, *CreateQuestionRequest) (*QuestionInfo, error)
	UpdateQuestion(context.Context, *UpdateQuestionRequest) (*emptypb.Empty, error)
	DeleteQuestion(context.Context, *DeleteQuestionRequest) (*emptypb.Empty, error)
	BatchImportQuestions(context.Context, *BatchImportQuestionsRequest) (*BatchImportQuestionsResponse, error)
	GetQuestionTagTaxonomy(context.Context, *emptypb.Empty) (*QuestionTagTaxonomyResponse, error)
	// === 题目流水线 ===
	GenerateQuestionPipeline(context.Context, *GenerateQuestionPipelineRequest) (*GenerateQuestionPipelineResponse, error)
	GenerateQuestionPipelineStream(*GenerateQuestionPipelineRequest, grpc.ServerStreamingServer[PipelineStreamEvent]) error
	GenerateQuestionPipelineAsync(context.Context, *GenerateQuestionPipelineRequest) (*PipelineTaskInfo, error)
	ImportQuestionPipeline(context.Context, *ImportQuestionPipelineRequest) (*BatchImportQuestionsResponse, error)
	// === 分类管理 ===
	AdminListCategories(context.Context, *emptypb.Empty) (*AdminListCategoriesResponse, error)
	CreateCategory(context.Context, *CreateCategoryRequest) (*CategoryInfo, error)
	UpdateCategory(context.Context, *UpdateCategoryRequest) (*emptypb.Empty, error)
	DeleteCategory(context.Context, *DeleteCategoryRequest) (*emptypb.Empty, error)
	// === 行业管理 ===
	AdminListIndustries(context.Context, *emptypb.Empty) (*AdminListIndustriesResponse, error)
	CreateIndustry(context.Context, *CreateIndustryRequest) (*IndustryInfo, error)
	UpdateIndustry(context.Context, *UpdateIndustryRequest) (*emptypb.Empty, error)
	// === Prompt 模板管理 ===
	ListPromptTemplates(context.Context, *ListPromptTemplatesRequest) (*ListPromptTemplatesResponse, error)
	SavePromptTemplate(context.Context, *SavePromptTemplateRequest) (*PromptTemplate, error)
	CreatePrompt(context.Context, *CreatePromptRequest) (*PromptTemplate, error)
	UpdatePrompt(context.Context, *UpdatePromptRequest) (*emptypb.Empty, error)
	DeletePrompt(context.Context, *DeletePromptRequest) (*emptypb.Empty, error)
	TestRenderPrompt(context.Context, *TestRenderPromptRequest) (*TestRenderPromptResponse, error)
	// === AI 配置 ===
	GetAIConfigs(context.Context, *emptypb.Empty) (*GetAIConfigsResponse, error)
	UpdateAIConfigs(context.Context, *UpdateAIConfigsRequest) (*emptypb.Empty, error)
	// === AI 预设管理 ===
	ListAIPresets(context.Context, *emptypb.Empty) (*ListAIPresetsResponse, error)
	SaveAIPreset(context.Context, *SaveAIPresetRequest) (*AIPreset, error)
	CreateAIPreset(context.Context, *CreateAIPresetRequest) (*AIPreset, error)
	UpdateAIPreset(context.Context, *UpdateAIPresetRequest) (*AIPreset, error)
	DeleteAIPreset(context.Context, *DeleteAIPresetRequest) (*emptypb.Empty, error)
	ApplyAIPreset(context.Context, *ApplyAIPresetRequest) (*GetAIConfigsResponse, error)
	// === AI 调试 & 日志 ===
	DebugAI(context.Context, *DebugAIRequest) (*DebugAIResponse, error)
	ListAICallLogs(context.Context, *ListAICallLogsRequest) (*ListAICallLogsResponse, error)
	GetAICallLog(context.Context, *GetAICallLogRequest) (*AICallLogDetail, error)
	// === Live2D 管理 ===
	ListLive2DModels(context.Context, *emptypb.Empty) (*ListLive2DModelsResponse, error)
	CreateLive2DModel(context.Context, *CreateLive2DModelRequest) (*Live2DModelInfo, error)
	UpdateLive2DModel(context.Context, *UpdateLive2DModelRequest) (*emptypb.Empty, error)
	DeleteLive2DModel(context.Context, *DeleteLive2DModelRequest) (*emptypb.Empty, error)
	ListSelectableLive2DModels(context.Context, *ListSelectableLive2DModelsRequest) (*ListSelectableLive2DModelsResponse, error)
	GetCurrentLive2DModel(context.Context, *GetCurrentLive2DModelRequest) (*CurrentLive2DModelResponse, error)
	ImportLive2DPackage(context.Context, *ImportLive2DPackageRequest) (*ImportLive2DPackageResponse, error)
	ImportLive2DBackground(context.Context, *ImportLive2DBackgroundRequest) (*ImportLive2DBackgroundResponse, error)
	// === TTS 管理 ===
	ListTTSConfigs(context.Context, *emptypb.Empty) (*ListTTSConfigsResponse, error)
	CreateTTSConfig(context.Context, *CreateTTSConfigRequest) (*TTSConfigInfo, error)
	UpdateTTSConfig(context.Context, *UpdateTTSConfigRequest) (*emptypb.Empty, error)
	DeleteTTSConfig(context.Context, *DeleteTTSConfigRequest) (*emptypb.Empty, error)
	UpdateTTSSceneDefaults(context.Context, *UpdateTTSSceneDefaultsRequest) (*emptypb.Empty, error)
	// === RAG 配置 ===
	GetRAGConfigs(context.Context, *emptypb.Empty) (*GetRAGConfigsResponse, error)
	UpdateRAGConfigs(context.Context, *UpdateRAGConfigsRequest) (*emptypb.Empty, error)
	TestRAGConnection(context.Context, *emptypb.Empty) (*TestRAGConnectionResponse, error)
	// === RAG 索引管理 ===
	IndexAllQuestions(context.Context, *IndexAllQuestionsRequest) (*IndexResult, error)
	IndexQuestions(context.Context, *IndexQuestionsRequest) (*IndexResult, error)
	DeleteRAGIndex(context.Context, *DeleteRAGIndexRequest) (*IndexResult, error)
	SearchRAGQuestions(context.Context, *SearchRAGQuestionsRequest) (*SearchRAGQuestionsResponse, error)
	// === RAG 文档管理 ===
	ListRAGDocuments(context.Context, *ListRAGDocumentsRequest) (*ListRAGDocumentsResponse, error)
	GetRAGDocumentStats(context.Context, *GetRAGDocumentStatsRequest) (*RAGDocumentStatsResponse, error)
	GetRAGDocument(context.Context, *GetRAGDocumentRequest) (*RAGDocumentDetail, error)
	CreateRAGDocument(context.Context, *CreateRAGDocumentRequest) (*RAGDocumentDetail, error)
	UpdateRAGDocument(context.Context, *UpdateRAGDocumentRequest) (*emptypb.Empty, error)
	DeleteRAGDocument(context.Context, *DeleteRAGDocumentRequest) (*emptypb.Empty, error)
	BatchImportRAGDocuments(context.Context, *BatchImportRAGDocumentsRequest) (*BatchImportRAGDocumentsResponse, error)
	SyncRAGDocumentsToVectorDB(context.Context, *SyncRAGDocumentsRequest) (*emptypb.Empty, error)
	SyncAllPendingRAGDocuments(context.Context, *emptypb.Empty) (*emptypb.Empty, error)
	// === 面经爬虫 ===
	GetScraperSources(context.Context, *emptypb.Empty) (*GetScraperSourcesResponse, error)
	ScraperSearch(context.Context, *ScraperSearchRequest) (*ScraperSearchResponse, error)
	ScraperFetch(context.Context, *ScraperFetchRequest) (*ScraperFetchResponse, error)
	ScraperClean(context.Context, *ScraperCleanRequest) (*ScraperCleanResponse, error)
	ScraperImport(context.Context, *ScraperImportRequest) (*ScraperImportResponse, error)
	ScraperImportAsync(context.Context, *ScraperImportRequest) (*ScraperTaskInfo, error)
	ListScraperTasks(context.Context, *ListScraperTasksRequest) (*ListScraperTasksResponse, error)
	GetScraperTask(context.Context, *GetScraperTaskRequest) (*ScraperTaskDetail, error)
	UpdateQuestionPipelineTask(context.Context, *UpdateQuestionPipelineTaskRequest) (*UpdateQuestionPipelineTaskResponse, error)
	RetryScraperTask(context.Context, *RetryScraperTaskRequest) (*ScraperTaskInfo, error)
	// === 系统配置 ===
	GetAdminConfig(context.Context, *GetAdminConfigRequest) (*AdminConfigValue, error)
	SetAdminConfig(context.Context, *SetAdminConfigRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedAdminServiceServer()
}

